      if (taskBlockStateIsTerminal(card.state) &&
          !board._pendingResumeLost.contains(card.id)) {
        board._emittedCardIds.add(card.id);
      }
      board._emittedSummaryTurns.add(card.turn);
    }
    return board;
  }

