        for (var i = 1; i <= 3; i++)
          custom('c$i', customType: 'model_request_summary'),
      ]);
      final report = await repairSessionLedgers(fs, path, dryRun: true);
      expect(report.recordsRead, 13);
      expect(
        report.recordsKept,
        10,
        reason: 'every contiguous message survives — span merging must not '
            'shrink the count',
      );
