          '${ids.isEmpty ? "(none)" : ids.join(", ")}';
    }
    try {
      await session.appendCustomEntry(
        customType: obligationsLedgerRecordType,
        data: payload,
      );
    } on Object {
      return 'marking $id ${parsed.jsonName} failed — the snapshot did not '
          'persist; try again';
