/// `partial`/`addedPartial` describe the last partial snapshot.
Future<
  ({AssistantMessage? finished, AssistantMessage? partial, bool addedPartial})
>
_consumeResponseStream(
  AssistantMessageEventStream response,
  Context context,
  AgentEventSink emit,

