      await fs.appendFile(
        path,
        '${custom('c2', customType: 'model_request_summary')}\n',
      );
      final beforeSecondRepair = (await fs.readTextFile(path)).getOrThrow();
      await repairSessionLedgers(fs, path);
      // The newest backup is the pre-second-repair file…
      expect(
