/// threads [roundCapEnded]), then let the detach summary name the jobs
/// — the documented degradation, never a silent hang.
Future<void> _finishHeadlessDrain(
  int drainMs, {
  required bool roundCapEnded,
}) async {
  if (isBusy) {
    await _settled;
