final class LedgerSnapshotThrottle {
  LedgerSnapshotThrottle({
    this.minInterval = ledgerSnapshotPersistInterval,
    DateTime Function()? clock,
    void Function()? onFlushDue,
  }) : _clock = clock ?? DateTime.now, _onFlushDue = onFlushDue;

  final Duration minInterval;
  final DateTime Function() _clock;
  final void Function()? _onFlushDue;

  DateTime? _lastPersistAt;
  DateTime? _pendingSince;
  Timer? _timer;

  /// True when a snapshot may append NOW...; false reserves the trailing flush.
  bool shouldPersistNow() {
    final last = _lastPersistAt;
    if (last == null || _clock().difference(last) >= minInterval) return true;
    _pendingSince ??= _clock();
    _arm();
    return false;
  }

  /// Trailing-flush check... tests call directly; production arrives via the Timer leg.
  bool poll() {
    final since = _pendingSince;
    if (since == null) return false;
    if (_clock().difference(since) < minInterval) return false;
    _pendingSince = null;
    return true;
  }

  void confirmPersisted() {
    _lastPersistAt = _clock();
    _pendingSince = null;
    _timer?.cancel(); _timer = null;
  }

  /// Production trailing leg — fires [poll]; a due flush calls [onFlushDue].
  void _arm() {
    if (_timer != null) return;
    _timer = Timer(minInterval, () {
      _timer = null;
      if (poll() && _onFlushDue != null) _onFlushDue!();
    });
  }

  /// New session (or shutdown): drop the memory and the trailing leg.
  void reset() { ... same as confirm + clear last }
  void dispose() { cancel timer }
```

