      expect(code, 1);
      expect(io.buffer.toString(), contains('is live'));
    });

    test('an unknown session fails cleanly', () async {
      final io = _RepairIo();
      final code = await runSessionRepairCliCommand(
        write: io.write,
        writeln: io.writeln,
        env: fs,
        sessionRoot: '/sessions',
