test('dry-run projects the bytesAfter the real repair produces (gh-1590)', () async {
  await writeSession([
    header(),
    for (var i = 1; i <= 5; i++) message('m$i'),
    for (var i = 1; i <= 3; i++)
      custom('c$i', customType: 'model_request_summary',
          data: {'pad': 'x' * 4000}),
    for (var i = 1; i <= 4; i++)
      custom('j$i', customType: 'shell_job_registry',
          data: {'gen': i, 'pad': 'y' * 2000}),
  ]);
  final dry = await repairSessionLedgers(fs, path, dryRun: true);
  expect(
    dry.bytesAfter,
    lessThan(dry.bytesBefore),
    reason: 'the dry run must show the reduction the repair would give — '
        'not bytesBefore parroting back',
  );
  expect(dry.bytesAfter, greaterThan(0));
  // The dry-run size line reads as a projection, not a no-op.
  expect(dry.summaryLines().last, contains('(projected)'));
  // Dropped bytes are accounted per ledger type.
  final droppedBytes = dry.droppedBytesByType.values
      .fold<int>(0, (a, b) => a + b);
  expect(droppedBytes, greaterThan(0));
  expect(
    dry.bytesBefore - dry.bytesAfter,
    droppedBytes,
    reason: 'kept spans + dropped spans partition the file',
  );
  expect(
    dry.summaryLines().join('\n'),
    contains('model_request_summary×'),
    reason: 'the per-type byte accounting names the ledger types',
  );

  // The real pass produces exactly the projected size.
  final real = await repairSessionLedgers(fs, path);
  expect(real.bytesAfter, dry.bytesAfter,
      reason: 'gh-1590 AC: the dry-run bytesAfter equals the real-run '
          'bytesAfter on the same fixture');
});
```

