  _LivePresence(this.id);

  final String id;

  @override
  Future<void> register(String sessionId, {int? pid, String? host}) async {}

  @override
  Future<void> touch(String sessionId) async {}

  @override
  Future<void> unregister(String sessionId) async {}

  @override
