  if (_headlessSubAgentsActive() || _headlessActiveShellJobs().isNotEmpty) {
    io.writeln(
      _style.dim(
        '⏳ background-job drain ${headlessDrainDetachCause(drainMs: drainMs, roundCapEnded: roundCapEnded)} '
